// Rebuilds the exact bytes Heardloop signed: JSON with sorted keys, no spaces, non-ASCII as \uXXXX.
const item = $input.first().json;
const h = item.headers || {};
const ts = String(h['x-heardloop-timestamp'] || '');
const signature = String(h['x-heardloop-signature'] || '');
const body = item.body;

function pyStr(s) {
  return JSON.stringify(s).replace(/[\u0080-￿]/g, c => '\\u' + c.charCodeAt(0).toString(16).padStart(4, '0'));
}
function canon(v) {
  if (v === null || v === undefined) return 'null';
  if (typeof v === 'boolean') return v ? 'true' : 'false';
  if (typeof v === 'number') return String(v);
  if (typeof v === 'string') return pyStr(v);
  if (Array.isArray(v)) return '[' + v.map(canon).join(',') + ']';
  return '{' + Object.keys(v).sort().map(k => pyStr(k) + ':' + canon(v[k])).join(',') + '}';
}

const age = Math.abs(Date.now() / 1000 - Number(ts));
return [{
  json: {
    toSign: ts + '.' + canon(body),
    signature,
    fresh: ts !== '' && Number.isFinite(age) && age <= 300,
    event: String(h['x-heardloop-event'] || (body && body.event) || ''),
    timestamp: ts,
    delivery: String(h['x-heardloop-delivery'] || ''),
    body,
  },
}];

// Verifies the signature in constant time, then passes on EVERYTHING Heardloop sent:
// summary fields for easy use, plus the full `data`, `post` and `payload` objects and the delivery headers.
const j = $input.first().json;
const expected = 'sha256=' + String(j.hmac || '');
const got = String(j.signature || '');
let diff = expected.length ^ got.length;
for (let i = 0; i < Math.min(expected.length, got.length); i++) diff |= expected.charCodeAt(i) ^ got.charCodeAt(i);
const valid = diff === 0 && j.fresh === true;

const alertEvents = ['post.failed', 'account.reconnect_needed', 'account.expiring', 'backup.failed', 'backup.stale'];
const b = j.body || {};
const post = b.post || null;
const data = b.data || {};
return [{
  json: {
    // check result
    valid,
    alert: alertEvents.includes(j.event),
    // delivery
    event: j.event,
    delivery: j.delivery,
    timestamp: j.timestamp,
    id: b.id || null,
    occurred_at: b.occurred_at || null,
    workspace_id: b.workspace_id || null,
    // post summary (null for events that are not about a post)
    post_id: post ? post.id || null : null,
    post_status: post ? post.status || null : null,
    post_url: post ? post.url || null : null,
    linkedin_url: post && post.linkedin_post_urn ? 'https://www.linkedin.com/feed/update/' + post.linkedin_post_urn + '/' : (data.linkedin_url || null),
    campaign_id: post ? post.campaign_id || null : null,
    scheduled_at: post ? post.scheduled_at || null : null,
    published_at: post ? post.published_at || null : null,
    // only when "Include the post text" is on in Heardloop
    post_text: post ? post.text || null : null,
    comment: data.comment || null,
    actor_name: data.actor_name || null,
    account_name: data.account_name || null,
    // codes and counts
    error: data.error || data.reason || null,
    // everything, untouched
    data,
    post,
    payload: b,
  },
}];
